OR c_id IN ( SELECT id from yz_xsgl_customer WHERE Co_Pid IN
#{Pid_arr}
)
and B.c_userId in
#{c_userIdArr}
AND B.code = A.Dio_Contract_ID
AND c_name LIKE CONCAT('%',#{value},'%')
AND c_name LIKE CONCAT('%',#{value},'%')
AND c_userName LIKE CONCAT('%',#{value},'%')
AND Dio_DsID IN
#{DsID_Arr}
AND Dio_Source_Type = #{Source_Type_Arr}
AND Ct_USERID =#{USERID}
ORDER BY c_time DESC LIMIT #{StarRow},#{PageSize};

